#!/usr/bin/env python3
"""Generate the content seed migration from app/content/packs.json (single source of truth)."""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
data = json.loads((root / 'app/content/packs.json').read_text(encoding='utf-8'))
q = lambda s: "null" if s is None else "'" + s.replace("'", "''") + "'"
arr = lambda xs: "array[" + ",".join(q(x) for x in xs) + "]::text[]" if xs else "'{}'::text[]"
out = ["-- Generated by scripts/build_seed_sql.py from app/content/packs.json — do not edit by hand.",
       "-- Idempotent upserts: re-run after editing packs.json and bumping its version."]
for si, p in enumerate(data['packs']):
    out.append(f"insert into public.spy_packs (id, name_ar, icon, mode, sort) values ({q(p['id'])}, {q(p['name_ar'])}, {q(p['icon'])}, {q(p['mode'])}, {si}) on conflict (id) do update set name_ar = excluded.name_ar, icon = excluded.icon, mode = excluded.mode, sort = excluded.sort, published = true, updated_at = now();")
    rows = [f"({q(p['id'])}, {q(i['id'])}, {q(i['name_ar'])}, {arr(i.get('roles_ar', []))}, {q(i.get('close_ar'))}, {k})" for k, i in enumerate(p['items'])]
    out.append("insert into public.spy_pack_items (pack_id, id, name_ar, roles_ar, close_ar, sort) values\n  " + ",\n  ".join(rows) + "\non conflict (pack_id, id) do update set name_ar = excluded.name_ar, roles_ar = excluded.roles_ar, close_ar = excluded.close_ar, sort = excluded.sort;")
out.append("insert into public.spy_dares (id, text_ar) values " + ", ".join(f"({k + 1}, {q(d)})" for k, d in enumerate(data['dares'])) + " on conflict (id) do update set text_ar = excluded.text_ar, published = true;")
out.append(f"update public.spy_dares set published = false where id > {len(data['dares'])};")
out.append("select setval(pg_get_serial_sequence('public.spy_dares', 'id'), (select max(id) from public.spy_dares));")
out.append(f"insert into public.spy_content_meta (id, version) values (true, {data['version']}) on conflict (id) do update set version = excluded.version, updated_at = now();")
(root / 'supabase/migrations/20261013000004_spy_seed_content.sql').write_text("\n".join(out) + "\n", encoding='utf-8')
print('ok', len(data['packs']))
